// .env.example generator (IPB-11-03, IPB-11 §11.4.3). The schema is the only source.
import { describeSchema, type EnvSchema, type EnvVarInfo } from "./schema.js";

export interface ExampleOptions {
  product?: string;
}

const COMMENT_COL = 47;

function group(v: EnvVarInfo): string {
  const m = /^(?:NEXT_PUBLIC_|EXPO_PUBLIC_)/.exec(v.name);
  if (m) return m[0];
  return v.name === "NODE_ENV" ? "APP_" : `${v.name.split("_")[0]}_`;
}

function line(v: EnvVarInfo): string {
  const left = `${v.name}=${v.meta.example}`;
  const prod = v.meta.prodExample ? `  (prod: ${v.meta.prodExample})` : "";
  return `${left.padEnd(COMMENT_COL - 1)} # ${v.meta.desc} · req:${v.meta.required} · sens:${v.meta.sens}${prod}`;
}

export function generateEnvExample(schema: EnvSchema, opts: ExampleOptions = {}): string {
  const vars = describeSchema(schema);
  const out = [
    "############################################################",
    `# Infrabyx ${opts.product ?? "<PRODUCT>"} — environment template (generated by infrabyx-env example; do not edit by hand)`,
    "# IPB-11 v1.0. Secrets (sens:S) MUST be secret:// references in staging/demo/pre-prod/prod/dr.",
    "############################################################",
  ];
  const groups = new Map<string, EnvVarInfo[]>();
  for (const v of vars) groups.set(group(v), [...(groups.get(group(v)) ?? []), v]);
  for (const [g, members] of groups)
    out.push("", `# ---------- ${g} ----------`, ...members.map(line));
  return `${out.join("\n")}\n`;
}

const nameOf = (l: string): string | null => /^([A-Z][A-Z0-9_]*)=/.exec(l)?.[1] ?? null;

/** Names whose lines differ between the committed file and the generated output. */
export function exampleDrift(committed: string, generated: string): string[] {
  const index = (t: string) =>
    new Map(t.split("\n").flatMap((l) => (nameOf(l) ? [[nameOf(l) as string, l] as const] : [])));
  const a = index(committed);
  const b = index(generated);
  const names = new Set([...a.keys(), ...b.keys()]);
  const drift = [...names].filter((n) => a.get(n) !== b.get(n));
  if (drift.length === 0 && committed !== generated) drift.push("(header or ordering)");
  return drift.sort();
}
